    steps: ["Coach dumps a puck into the far corner; two players race from the blue line to get it.","The winner must gain possession and pass it back to the coach before the whistle.","Loser does five push-ups while the next pair lines up.","Run eight races per player, alternating which corner the puck goes to."],
    coachingPoints: ["The chase is full effort \u2014 jogging after the puck builds nothing.","Win the puck and make one clean play; the sprint continues after possession.","Keep the shifts short so every chase is at true game speed."],
    diagram:{surface:"hockey-full",markers:[{x:6,y:35,kind:"player"},{x:6,y:50,kind:"player"},{x:6,y:65,kind:"player"},{x:50,y:80,kind:"coach",label:"C"}],arrows:[{from:[10,42],to:[90,42],style:"run"},{from:[90,58],to:[10,58],style:"run"}]},
