    setup: "No pucks for the first four reps. Players at the blue line, coach timing.",
    steps: ["Players line up at one blue line and sprint to the far blue line and back.","Rest thirty seconds, then repeat; run six reps.","On the last two reps, players carry a puck to keep the hands working under fatigue.","Coach tracks times; the group goal is consistency, not just one fast rep."],
    coachingPoints: ["Sprint every rep \u2014 this only works at full effort.","Recover fully between reps; the goal is speed endurance, not exhaustion.","Keep the form clean when tired; sloppy skating when fatigued causes injuries."],
    diagram:{surface:"hockey-full",markers:[{x:6,y:35,kind:"player"},{x:6,y:50,kind:"player"},{x:6,y:65,kind:"player"},{x:50,y:80,kind:"coach",label:"C"}],arrows:[{from:[10,42],to:[90,42],style:"run"},{from:[90,58],to:[10,58],style:"run"}]},
